from taf.gnb.oam.coam.cu.schemas.internal.asm.vms_info_v1 import VMSInfov1


class VMSInfoLicensedV1(VMSInfov1):
    def __init__(self, id, name, hostname, role, availability_status, operational_state, software_version, alarms,
                 ip_interfaces, dist_names, cores, cpu_load, memory_total, memory_used):
        self.id = id
        self.name = name
        self.hostname = hostname
        self.role = role
        self.availability_status = availability_status
        self.operational_state = operational_state
        self.software_version = software_version
        self.alarms = alarms
        self.ip_interfaces = ip_interfaces
        self.dist_names = dist_names
        self.cores = cores
        self.cpu_load = cpu_load
        self.memory_total = memory_total
        self.memory_used = memory_used

        super(VMSInfoLicensedV1, self).__init__(id, name, hostname, role, availability_status, operational_state,
                                                software_version, alarms, ip_interfaces, dist_names, cores, cpu_load,
                                                memory_total, memory_used)
